message.content:
{
  "lesson_summary": "Today's lesson plans to teach students to identify and count numbers from 0 to 9. It will cover showing these numbers in various forms, such as objects, drawings, and fingers, and matching them to their corresponding numerals. The lesson will use examples like chalk dots, hands showing fingers, petals, tree branches, and stem leaves to illustrate these concepts.",
  "lesson_summary_short": "Today's lesson plans to teach identifying and counting numbers from 0 to 9, using examples like chalk dots.",
  "checks_summary": "This quiz checks whether the class can identify and count numbers from 0 to 9, and represent them using objects, drawings, or fingers.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "Which of these is a 'numeral'?",
      "options": [
        "7",
        "seven dots",
        "a hand"
      ],
      "correct_index": 0,
      "explanation": "A numeral is a symbol or sign used to represent a number. The symbol '7' represents the number seven.",
      "selected_because": "The lesson introduced the term 'numeral' and its meaning.",
      "distractor_misconceptions": {
        "1": "Confuses the numeral with the quantity it represents.",
        "2": "Confuses the numeral with a way to show a number."
      },
      "option_feedback": {
        "correct": "That's right! A numeral is the written symbol for a number, like '7'.",
        "wrong": {
          "1": "Seven dots show the quantity of seven, but 'numeral' refers to the written symbol. The numeral for seven is '7'.",
          "2": "A hand can show a number with fingers, but 'numeral' is the written symbol. The numeral for seven is '7'."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "How many chalk dots are shown in the picture?",
      "options": [
        "7",
        "6",
        "5"
      ],
      "correct_index": 0,
      "explanation": "By pointing to each dot once and saying one number word for each, you will count seven dots.",
      "selected_because": "The worked example of counting chalk dots on the board.",
      "distractor_misconceptions": {
        "1": "Miscounts by skipping one dot or counting one twice.",
        "2": "Miscounts by guessing rather than one-to-one correspondence."
      },
      "option_feedback": {
        "correct": "Excellent! There are 7 chalk dots. You counted each one carefully.",
        "wrong": {
          "1": "Remember to point to each dot only once and say one number word for each. Count them again to find the 7 dots.",
          "2": "It's important to count each dot one by one. If you count carefully, you will find there are 7 dots."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "counter",
        "count": 7
      },
      "figure_role": "read_off"
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "Which picture shows 2 fingers?",
      "options": [
        "P",
        "Q",
        "R"
      ],
      "correct_index": 1,
      "explanation": "Picture Q clearly shows two fingers raised, representing the number 2.",
      "selected_because": "Matching hands with raised fingers to numerals.",
      "distractor_misconceptions": {
        "0": "Confuses the number 0 with the number 2.",
        "2": "Confuses the number 1 with the number 2."
      },
      "option_feedback": {
        "correct": "You got it! Picture Q shows exactly 2 raised fingers.",
        "wrong": {
          "0": "Picture P shows an open hand, which means zero fingers. Look for the picture with two fingers raised.",
          "2": "Picture R shows only one raised finger. Look for the picture with two fingers raised."
        }
      },
      "figure": {
        "type": "match",
        "left": [
          {
            "picto": "hand",
            "count": 0,
            "label": "P"
          },
          {
            "picto": "hand",
            "count": 2,
            "label": "Q"
          },
          {
            "picto": "hand",
            "count": 1,
            "label": "R"
          }
        ],
        "right": []
      },
      "figure_role": "read_off"
    },
    {
      "slo_id": "S4",
      "level": "apply",
      "question": "If you see a drawing of a big tree with only two branches, what number does it show?",
      "options": [
        "2",
        "5",
        "8"
      ],
      "correct_index": 0,
      "explanation": "The number is determined by counting the individual branches, not by the overall size of the tree drawing. Two branches mean the number 2.",
      "selected_because": "The misconception about guessing from drawing size vs. counting parts.",
      "distractor_misconceptions": {
        "1": "Guesses the number based on the drawing's size.",
        "2": "Guesses a large number because the drawing is big."
      },
      "option_feedback": {
        "correct": "That's right! Even if the tree is big, you count the branches one by one. Two branches mean the number 2.",
        "wrong": {
          "1": "Remember, the size of the drawing doesn't tell you the number. You need to count each part, like the branches. A big tree with two branches shows the number 2.",
          "2": "It's easy to think a big drawing means a big number, but we always count each part. A big tree with two branches shows the number 2."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "Which of these shows the number 5 using objects?",
      "options": [
        "Five apples",
        "The numeral '5'",
        "A drawing of a hand"
      ],
      "correct_index": 0,
      "explanation": "Objects are physical items. Five apples are physical items that represent the number 5.",
      "selected_because": "Showing numbers in different forms (objects, drawings, fingers).",
      "distractor_misconceptions": {
        "1": "Confuses an object representation with a numeral.",
        "2": "Confuses an object representation with a drawing."
      },
      "option_feedback": {
        "correct": "Yes, five apples are objects that show the number 5. Great job!",
        "wrong": {
          "1": "The numeral '5' is a symbol, not an object. Five apples are objects that show the number 5.",
          "2": "A drawing of a hand is a drawing, not an object itself. Five apples are objects that show the number 5."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "How many petals are shown in the picture?",
      "options": [
        "9",
        "8",
        "7"
      ],
      "correct_index": 0,
      "explanation": "Counting each petal one by one reveals there are 9 petals in the picture.",
      "selected_because": "Practicing counting petals at the bottom of a picture.",
      "distractor_misconceptions": {
        "1": "Miscounts by one or two, possibly due to skipping or recounting.",
        "2": "Underestimates the count, possibly from a quick glance."
      },
      "option_feedback": {
        "correct": "Exactly! There are 9 petals. You counted them correctly.",
        "wrong": {
          "1": "Let's count them again slowly, pointing to each petal as you say the number. You will find there are 9 petals.",
          "2": "Make sure to count every single petal. If you count carefully, you will see there are 9 petals."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "flower",
        "count": 9
      },
      "figure_role": "read_off"
    },
    {
      "slo_id": "S4",
      "level": "apply",
      "question": "If you draw 4 stem leaves, which numeral should you write?",
      "options": [
        "4",
        "6",
        "9"
      ],
      "correct_index": 0,
      "explanation": "The numeral you write should match the last number word you said when counting the leaves. If you counted four leaves, you write the numeral '4'.",
      "selected_because": "Drawing and counting stem leaves, then writing the numeral.",
      "distractor_misconceptions": {
        "1": "Confuses the count with a different number.",
        "2": "Chooses a random higher number."
      },
      "option_feedback": {
        "correct": "That's right! If you draw 4 stem leaves, you write the numeral '4'.",
        "wrong": {
          "1": "The numeral you write should always match the number of things you counted. If you drew 4 leaves, you write '4'.",
          "2": "Always write the numeral that matches your count. If you drew 4 leaves, the numeral is '4'."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "Which of these is the numeral for 'zero'?",
      "options": [
        "0",
        "an open hand",
        "a blank space"
      ],
      "correct_index": 0,
      "explanation": "The numeral '0' is the symbol used to represent the number zero, which means nothing or none.",
      "selected_because": "Identifying numbers from 0 to 9, including zero.",
      "distractor_misconceptions": {
        "1": "Confuses the numeral with a way to show zero using fingers.",
        "2": "Confuses the numeral with the concept of nothingness."
      },
      "option_feedback": {
        "correct": "Correct! The numeral '0' represents zero, meaning nothing.",
        "wrong": {
          "1": "An open hand shows zero fingers, but '0' is the numeral, the written symbol for zero.",
          "2": "A blank space might mean nothing is there, but the numeral for zero is the symbol '0'."
        }
      },
      "figure": null,
      "figure_role": null
    }
  ]
}
